package com.bte.service;
import com.bte.entity.*;import com.bte.dto.*;import com.bte.enums.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class MultiMatchScoringTest {
 private MatchRanking row(long id,int rank,int points,int kills){var r=new MatchRanking(id,rank,kills,"Team "+id);r.setPlacementPoints(points);return r;}
 @Test void cumulativeWinnerCanDifferFromLastRoundWinner(){var first=MatchResult.builder().rankings(List.of(row(1,1,10,8),row(2,2,5,0))).build();var last=MatchResult.builder().rankings(List.of(row(1,2,5,0),row(2,1,10,0))).build();var table=TournamentStandingsService.aggregate(List.of(first,last),List.of());assertEquals(1L,table.getFirst().captainUserId());assertEquals(23,table.getFirst().totalPoints());assertEquals(2,table.getFirst().roundsPlayed());}
 @Test void tieBreakUsesKillsThenLatestPlacement(){var match=MatchResult.builder().rankings(List.of(row(1,1,10,0),row(2,2,5,5))).build();assertEquals(2L,TournamentStandingsService.aggregate(List.of(match),List.of()).getFirst().captainUserId());}
 @Test void claimedCaptainIsAggregatedToCurrentOwner(){var match=MatchResult.builder().rankings(List.of(row(10,1,10,2))).build();var entry=Registration.builder().ownerUserId(20L).guestAccountId(10L).teamName("Claimed").build();assertEquals(20L,TournamentStandingsService.aggregate(List.of(match),List.of(entry)).getFirst().captainUserId());}
 private Registration entry(){var t=Tournament.builder().plannedRounds(2).squadSize(2).build();var member=new SquadMember("Member","member-uid");member.setWalletUserId(2L);return Registration.builder().id(7L).tournament(t).ownerUserId(1L).paymentStatus(PaymentStatus.PAID).squadMembers(List.of(new SquadMember("Captain","captain-uid"),member)).build();}
 @Test void individualKillsMustSumToTeamKills(){var r=entry();assertThrows(com.bte.exception.BadRequestException.class,()->RoundScoreRules.validate(r.getTournament(),List.of(r),List.of(new MatchRankingRequest(1L,1,99,"Team",10,Map.of(1L,2,2L,3)))));}
 @Test void everySeatMustBeScored(){var r=entry();assertThrows(com.bte.exception.BadRequestException.class,()->RoundScoreRules.validate(r.getTournament(),List.of(r),List.of(new MatchRankingRequest(1L,1,2,"Team",10,Map.of(1L,2)))));}
 @Test void correctRosterProducesIndividualScores(){var r=entry();var scores=RoundScoreRules.validate(r.getTournament(),List.of(r),List.of(new MatchRankingRequest(1L,1,5,"Team",10,Map.of(1L,2,2L,3))));assertEquals(2,scores.size());assertEquals(5,scores.stream().mapToInt(MatchPlayerScore::getKills).sum());}
 @Test void csvEscapesQuotesAndFormulaPrefixes(){assertEquals("\"a,\"\"b\"\"\"",LedgerCsv.cell("a,\"b\""));assertEquals("\"'=SUM(A1)\"",LedgerCsv.cell("=SUM(A1)"));assertTrue(LedgerCsv.cell("\t@SUM(A1)").startsWith("\"'"));assertTrue(LedgerCsv.line(1,"ref").endsWith("\r\n"));}
}
